const upsertUpsDevice = `-- name: UpsertUpsDevice :one

INSERT INTO ups_devices (server_id, ups_name, description)
VALUES ($1, $2, $3)
ON CONFLICT (server_id, ups_name) DO UPDATE
SET description = EXCLUDED.description,
    present = TRUE
RETURNING id, server_id, ups_name, description, manufacturer, model, serial, firmware, driver, status, state, reachability, vars, var_descriptions, present, last_reading_at, created_at, updated_at
`

type UpsertUpsDeviceParams struct {
	ServerID    uuid.UUID `json:"server_id"`
	UpsName     string    `json:"ups_name"`
	Description string    `json:"description"`
}

// UPS devices, their readings and their power events (000131).
// Keyed on (server_id, ups_name), NUT's own identity, so a device keeps its id
// and history across polls, restarts and a ups.conf edit that drops and then
// restores it.
func (q *Queries) UpsertUpsDevice(ctx context.Context, arg UpsertUpsDeviceParams) (UpsDevice, error) {
	row := q.db.QueryRow(ctx, upsertUpsDevice, arg.ServerID, arg.UpsName, arg.Description)
	var i UpsDevice
	err := row.Scan(
		&i.ID,
		&i.ServerID,
		&i.UpsName,
		&i.Description,
		&i.Manufacturer,
		&i.Model,
		&i.Serial,
		&i.Firmware,
		&i.Driver,
		&i.Status,
		&i.State,
		&i.Reachability,
		&i.Vars,
		&i.VarDescriptions,
		&i.Present,
		&i.LastReadingAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
